"""Build revised-SRD race references and a small, original book-race summary catalog."""
import re,json,html,sys
from pathlib import Path
src=Path(sys.argv[1]);root=Path(__file__).resolve().parents[1]
def section(file,id):
 s=(src/file).read_text();hs=list(re.finditer(r'<h([1-6])\b[^>]*id="([^"]+)"[^>]*>.*?</h[1-6]>',s,re.S));m=next(x for x in hs if x[2]==id);end=next((x.start() for x in hs if x.start()>m.start() and int(x[1])<=int(m[1])),s.find('</body>'));return s[m.end():end]
def plain(s):
 s=re.sub(r'</(?:p|li|tr|h[1-6]|div|ul|table)>','\n\n',s);s=re.sub(r'</(?:td|th)>',' | ',s)
 return '\n\n'.join(re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]+>',' ',x))).strip(' |') for x in s.split('\n\n') if re.sub('<[^>]+>','',x).strip())
def ref(file,id):
 folder='psionics' if file.startswith('psionic') else 'monsters' if file.startswith('monsters') else 'basic-rules-and-legal'
 return 'https://olimot.github.io/srd-v3.5/'+folder+'/'+file+'#'+id
races=[]
def add(id,name,group,file,anchor,**kw):
 r=dict(id=id,name=name,group=group,abilities={},size='Medium',speed=30,type='Humanoid',vision='Normal vision',languages=['Common'],bonusLanguages='See reference',favoredClass='Any',la=0,rhd=0,hitDice='None',natural=0,dodge=0,skills={},saves={},powerPoints=0,grapple=0,traits=[],source=ref(file,anchor),book='Revised 3.5 SRD',openGame=True,reference=plain(section(file,anchor)))
 r.update(kw);races.append(r);return r
def variant(id,name,base,file,anchor,**kw):
 parent=next(r for r in races if r['id']==base);r={**parent,'id':id,'name':name,'group':'Subraces','source':ref(file,anchor),'reference':'BASE RACE\n\n'+parent['reference']+'\n\nSUBRACE CHANGES\n\n'+plain(section(file,anchor))};r.update(kw);races.append(r);return r
