# Book races contain original short summaries, not reproduced book passages.
def bookrace(id,name,book,source,**kw):
 r=dict(id=id,name=name,group='Other books',abilities={},size='Medium',speed=30,type='Humanoid',vision='Normal vision',languages=['Common'],bonusLanguages='See book',favoredClass='Any',la=0,rhd=0,hitDice='None',natural=0,dodge=0,skills={},saves={},powerPoints=0,grapple=0,traits=[],source=source,book=book,openGame=False,reference='');r.update(kw);races.append(r)
eberron='https://srd.dndtools.org/srd/races/racesEberron.html'
bookrace('changeling','Changeling','Eberron Campaign Setting',eberron,type='Humanoid (shapechanger)',favoredClass='Rogue',skills={'Bluff':2,'Intimidate':2,'Sense Motive':2},traits=['Sleep/charm saves +2. Speak Language is a class skill.','At-will physical disguise: full-round action, possessions unchanged, +10 Disguise when used. See book for limitations.'])
bookrace('warforged','Warforged','Eberron Campaign Setting',eberron,abilities={'CON':2,'WIS':-2,'CHA':-2},type='Construct (living construct)',favoredClass='Fighter',traits=['Composite plating: armor +2, arcane failure 5%; enter in Combat. Does not stack with armor.','Light fortification 25%; slam 1d4.','No eating, breathing, or sleeping. Ordinary healing works at half strength; lethal damage does not heal naturally.','Immune to poison, sleep, paralysis, disease, nausea, fatigue, exhaustion, sickening, and energy drain. Consult living-construct exceptions.'])
stone='https://srd.dndtools.org/srd/races/racesRos.html'
bookrace('goliath','Goliath','Races of Stone',stone,abilities={'STR':4,'DEX':-2,'CON':2},type='Monstrous humanoid',favoredClass='Barbarian',languages=['Common','Gol-Kaa'],la=1,grapple=4,skills={'Sense Motive':2},traits=['Powerful build permits larger weapons and favorable size treatment for opposed checks; actual size and reach stay Medium.','Standing jumps count as running jumps; accelerated climbing avoids its usual penalty. Acclimated to high altitude.'])
bookrace('whisper-gnome','Whisper Gnome','Races of Stone',stone,abilities={'DEX':2,'CON':2,'STR':-2,'CHA':-2},size='Small',type='Humanoid (gnome)',vision='Darkvision 60 ft.; low-light vision',languages=['Common','Gnome'],favoredClass='Rogue',skills={'Hide':4,'Move Silently':4,'Listen':2,'Spot':2},traits=['Hooked-hammer familiarity. Attacks against kobolds/goblinoids +1; dodge AC against giants +4.','Silence centered on self 1/day. With CHA 10+, ghost sound, mage hand, and message each 1/day; caster level 1.'])
for r in races:
 if r['openGame']:
  m=re.search(r'Bonus Languages?:\s*(.*?)(?:\n\n|$)',r['reference'])
  if m:r['bonusLanguages']=m[1].strip()
assert len(races)==35,len(races)
assert len(set(r['id'] for r in races))==len(races)
(root/'lib/race-data.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='reference'} for r in races],ensure_ascii=False,separators=(',',':')))
(root/'public/data/races.json').write_text(json.dumps(races,ensure_ascii=False,separators=(',',':')))
print(json.dumps({'races':len(races),'core':sum(r['group']=='Core' for r in races),'srd':sum(r['openGame'] for r in races)}))
